import {encounters,judgeInput} from './arcade-scenes.mjs';
const $=id=>document.getElementById(id), videos=[$('film-a'),$('film-b')];
let manifest={},room=0,lives=3,score=0,mode='arcade',phase='title',previousPhase='',active=null,muted=false,token=0,raf=0,resolved=false,cueShown=false,openAt=0,closeAt=0,won=false,awarded=false,started=false;
const current=()=>encounters[room];
const setStatus=text=>$('status').textContent=text;
function button(text,fn,secondary=false){const b=document.createElement('button');b.textContent=text;b.className=secondary?'secondary':'gold';b.onclick=()=>{b.disabled=true;fn();};return b;}
function modal(kicker,title,copy,actions){$('overlay-kicker').textContent=kicker;$('overlay-title').textContent=title;$('overlay-copy').textContent=copy;$('overlay-actions').replaceChildren(...actions);$('overlay').hidden=false;$('overlay-title').focus({preventScroll:true});}
function closeModal(){$('overlay').hidden=true;}
function hud(){$('chapter').textContent=current().chapter;$('room-count').textContent=`ROOM ${room+1} / ${encounters.length}`;$('lives').textContent=mode==='guided'?'GUIDED · TAKE YOUR TIME':`${'◆'.repeat(lives)}${'◇'.repeat(3-lives)} · ${score} POINTS`;}
function getClip(id){const entry=manifest.clips?.[id];if(!entry?.src)throw Error(`Missing clip: ${id}`);const u=new URL(entry.src,location.origin);if(u.protocol!=='https:'&&u.origin!==location.origin)throw Error('Invalid video address');return u.href;}
async function loadManifest(){const response=await fetch('/arcade-media.json',{cache:'no-cache'});if(!response.ok)throw Error('The films could not be loaded.');manifest=await response.json();if(!manifest.clips)throw Error('The films could not be loaded.');}
function preloadOutcomes(){for(const type of ['win','fail']){const link=document.createElement('link');link.rel='prefetch';link.as='video';link.href=getClip(`${current().id}-${type}`);document.head.append(link);}}
function failMedia(message){cancelAnimationFrame(raf);active?.pause();phase='error';$('cue-panel').hidden=true;$('pause').hidden=true;modal('THE FILM NEEDS A MOMENT','Let’s try that again.',message,[button('Reload this room',()=>playRoom()),button('Back to title',()=>location.reload(),true)]);}
async function playClip(id,nextPhase){
 const mine=++token;cancelAnimationFrame(raf);phase='loading';$('cue-panel').hidden=true;closeModal();$('toast').textContent='Loading the film…';$('pause').hidden=true;
 const next=videos.find(v=>v!==active)||videos[0];next.pause();next.onended=null;next.onerror=null;next.muted=muted;next.loop=false;next.src=getClip(id);next.load();
 try{await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{cleanup();reject(Error('The video took too long to load. Check your connection and retry.'));},30000);const cleanup=()=>{clearTimeout(timeout);next.removeEventListener('canplay',ok);next.removeEventListener('error',bad);};const ok=()=>{cleanup();resolve();};const bad=()=>{cleanup();reject(Error('This video could not be played. Please retry.'));};next.addEventListener('canplay',ok);next.addEventListener('error',bad);if(next.readyState>=3)ok();});
 if(mine!==token)return;active?.pause();videos.forEach(v=>v.hidden=v!==next);active=next;phase=nextPhase;$('toast').textContent='';$('pause').hidden=false;$('pause').textContent='Pause Ⅱ';
 active.onerror=()=>{if(mine===token)failMedia('The film was interrupted. Retry this room without losing a life.');};
 active.onended=()=>{if(mine!==token)return;if(phase==='threat')resolveMove(false);else if(phase==='outcome')finishOutcome();};
 if(nextPhase==='threat'){openAt=active.duration*current().open;closeAt=active.duration*current().close;preloadOutcomes();}
 try{await active.play();}catch{pauseGame(true);return;}
 if(mine!==token)return;
 if(document.hidden){pauseGame();return;}
 if(nextPhase==='threat')raf=requestAnimationFrame(tick);
 setStatus(nextPhase==='threat'?'WATCH THE SCENE · WAIT FOR YOUR CUE':won?'GOOD MOVE':'A COMEDIC SETBACK');
 }catch(err){if(mine===token)failMedia(err.message);}
}
function showCue(){cueShown=true;$('cue-text').textContent=current().cue;$('cue-panel').hidden=false;$('moves').replaceChildren(...current().choices.map(choice=>{const b=button('',()=>move(choice.id));b.className='move';const icon=document.createElement('span');icon.className='icon';icon.textContent=choice.icon;icon.setAttribute('aria-hidden','true');const text=document.createElement('span'),label=document.createElement('b'),key=document.createElement('small');label.textContent=choice.label;key.textContent=choice.key;text.append(label,key);b.append(icon,text);return b;}));$('toast').textContent='';if(mode==='guided'){active.pause();setStatus('GUIDED MODE · CHOOSE WHEN READY');}}
function tick(){if(phase!=='threat'||resolved)return;const t=active.currentTime;if(t>=openAt&&!cueShown)showCue();if(cueShown){const left=mode==='guided'?100:Math.max(0,(closeAt-t)/(closeAt-openAt)*100);$('time-bar').style.transform=`scaleX(${left/100})`;$('countdown').setAttribute('aria-valuenow',String(Math.round(left)));}if(mode==='arcade'&&t>closeAt){resolveMove(false);return;}raf=requestAnimationFrame(tick);}
function move(id){if(phase!=='threat'||resolved)return;if(!cueShown){$('toast').textContent='Watch closely—the move cue is coming.';return;}const verdict=judgeInput(active.currentTime,openAt,mode==='guided'?Infinity:closeAt,id,current().correct);if(verdict==='early')return;resolveMove(verdict==='win');}
function resolveMove(success){if(resolved||phase!=='threat')return;resolved=true;won=success;cancelAnimationFrame(raf);active.pause();$('cue-panel').hidden=true;if(!success&&mode==='arcade')lives=Math.max(0,lives-1);hud();playClip(`${current().id}-${success?'win':'fail'}`,'outcome');}
function finishOutcome(){if(won&&!awarded){score+=100;awarded=true;hud();}phase='result';$('pause').hidden=true;setStatus(won?'ROOM CLEARED':'TRY A DIFFERENT MOVE');if(won){modal(current().success,room===2?'You earned your gold.':'Nicely played.',current().lesson,[button(room===2?'Complete the quest →':'Next room →',()=>{if(room===2)complete();else{room++;playRoom();}})]);}else if(lives===0&&mode==='arcade'){modal('OUT OF LIVES','The lair wins. This time.',`${current().failure} Restart with three fresh lives, or practice this room without a timer.`,[button('Start a new quest',start),button('Practice this room',()=>{mode='guided';playRoom();},true)]);}else{modal('A MINOR SETBACK',current().failure,'Watch the danger and choose a different move. Your checkpoint is right here.',[button('Retry this room ↺',playRoom)]);}}
async function playRoom(){phase='loading';closeModal();$('cue-panel').hidden=true;$('toast').textContent='Loading the film…';try{await loadManifest();}catch(e){failMedia(e.message);return;}resolved=false;cueShown=false;awarded=false;hud();$('poster').src=`/assets/${current().art}.webp`;$('poster').alt='';$('toast').textContent='';playClip(`${current().id}-threat`,'threat');}
async function start(){if(phase==='loading')return;mode=$('difficulty').value;room=0;lives=3;score=0;started=true;$('title-card').hidden=true;$('cabinet').classList.add('in-game');$('lives').hidden=false;$('restart').hidden=false;closeModal();phase='loading';try{if(!manifest.clips)await loadManifest();playRoom();}catch(e){failMedia(e.message);}}
function complete(){phase='complete';$('pause').hidden=true;$('room-count').textContent='QUEST COMPLETE';setStatus('CREDIT’S LAIR · POWERED BY ARCADEENGINE');modal('THE GOLDEN OFFER · COMPLETE','Rich in gold. Richer in judgment.',`Three rooms survived. ${score} points. You kept 1,000 coins, avoided the 820-coin contract, and earned 400 more. Final purse: 1,400 coins. Try Arcade mode for timed moves, or replay to discover the comic failures.`,[button('Play again ↺',start),button('Explore the longer illustrated story',()=>location.href='/story.html',true)]);}
function pauseGame(playbackBlocked=false){if(!['threat','outcome'].includes(phase))return;previousPhase=phase;phase='paused';active.pause();cancelAnimationFrame(raf);$('cue-panel').hidden=true;$('pause').textContent='Resume ▶';modal('INTERMISSION',playbackBlocked?'Ready when you are.':'Take a breath.','The film and your move timer are paused.',[button('Resume the film ▶',resume)]);}
async function resume(){if(phase!=='paused')return;phase=previousPhase;closeModal();$('pause').textContent='Pause Ⅱ';if(phase==='threat'&&cueShown)$('cue-panel').hidden=false;try{if(!(mode==='guided'&&phase==='threat'&&cueShown))await active.play();if(phase==='threat')raf=requestAnimationFrame(tick);}catch{pauseGame(true);}}
$('start').onclick=start;$('pause').onclick=()=>phase==='paused'?resume():pauseGame();$('sound').onclick=()=>{muted=!muted;videos.forEach(v=>v.muted=muted);$('sound').textContent=muted?'Sound off':'Sound on';$('sound').setAttribute('aria-pressed',String(!muted));};
$('restart').onclick=()=>{if(phase==='loading')return;if(['threat','outcome'].includes(phase))pauseGame();const restore=phase==='paused'?resume:()=>{if(phase==='complete')complete();else finishOutcome();};modal('START OVER?','Return to the castle gate?','This resets your current quest and restores three lives.',[button('Restart quest',start),button('Keep playing',restore,true)]);};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else $('toast').textContent='Use your browser’s full-screen control.';}catch{$('toast').textContent='Full screen is unavailable in this browser.';}};
window.addEventListener('keydown',e=>{if(e.repeat||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(e.key==='Escape'||e.key.toLowerCase()==='p'){if(['threat','outcome','paused'].includes(phase)){e.preventDefault();phase==='paused'?resume():pauseGame();}return;}if(phase!=='threat')return;let id;const key=e.key.toLowerCase();if(room===2){if(['arrowdown','s',' '].includes(key))id='duck';if(['arrowup','w'].includes(key))id='strike';}else{if(['arrowleft','a','1'].includes(key))id=current().choices[0].id;if(['arrowright','d','2'].includes(key))id=current().choices[1].id;}if(id){e.preventDefault();move(id);}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&started)pauseGame();});
